async def act(page):
    """Search for the article and check whether it contains an image related to 'Jazz Gough'.

    Steps:
    - Use create_curated_collection_by_search to drive the visible search UI and obtain candidate posts.
    - Inspect returned results for a title that contains both 'social supermarket' and 'christmas'.
    - Navigate to the found article (use a relative goto when same-origin).
    - Use accessibility-role-centric selectors to look for an image related to 'Jazz Gough':
      1) role-based lookup for an img with accessible name 'Jazz Gough'
      2) iterate all role='img' elements and check alt/title/aria-label attributes
      3) fallback to searching visible text 'Jazz Gough' on the page
    - Print exactly 'YES' if evidence is found, otherwise print 'NO'.
    """
    import urllib.parse

    # Keywords to try via the visible search helper
    keywords = [
        "Social supermarket 'helps me to afford Christmas'",
        "Social supermarket helps me to afford Christmas",
        "Social supermarket Christmas",
    ]

    target_url = None

    # Use the KB helper that interacts with the site's complementary search widget.
    for kw in keywords:
        try:
            results = await create_curated_collection_by_search(page, kw, max_results=0, resolve_links=True)
        except Exception:
            results = []

        for item in results:
            title = (item.get('title') or '').strip()
            url = item.get('url')
            if not title or not url:
                continue
            t = title.lower()
            if 'social supermarket' in t and 'christmas' in t:
                target_url = url
                break
        if target_url:
            break

    if not target_url:
        # Could not locate the article via the visible search
        print('NO')
        return

    # Navigate to the article using a relative goto when possible
    parsed = urllib.parse.urlparse(target_url)
    cur = urllib.parse.urlparse(page.url)
    if parsed.netloc == '' or parsed.netloc == cur.netloc:
        rel = parsed.path or '/'
        if parsed.query:
            rel += '?' + parsed.query
        await page.goto(rel)
    else:
        await page.goto(target_url)

    # Wait defensively for main content or network idle
    try:
        main_locator = page.get_by_role('main')
        await main_locator.wait_for(timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    found = False

    # 1) Try role-based lookup for an img with accessible name containing 'Jazz Gough'
    try:
        img_by_name = page.get_by_role('img', name='Jazz Gough')
        if await img_by_name.count() > 0:
            found = True
    except Exception:
        pass

    # 2) Iterate all images and check alt/title/aria-label attributes
    if not found:
        try:
            imgs = page.get_by_role('img')
            n = await imgs.count()
            for i in range(n):
                alt = None
                title_attr = None
                aria = None
                try:
                    alt = await imgs.nth(i).get_attribute('alt')
                except Exception:
                    alt = None
                try:
                    title_attr = await imgs.nth(i).get_attribute('title')
                except Exception:
                    title_attr = None
                try:
                    aria = await imgs.nth(i).get_attribute('aria-label')
                except Exception:
                    aria = None

                combined = ' '.join([x for x in [alt or '', title_attr or '', aria or ''] if x])
                if combined and 'jazz gough' in combined.lower():
                    found = True
                    break
        except Exception:
            pass

    # 3) Fallback: search visible text 'Jazz Gough' (caption/credit)
    if not found:
        try:
            text_locator = page.get_by_text('Jazz Gough', exact=False)
            if await text_locator.count() > 0:
                found = True
        except Exception:
            pass

    print('YES' if found else 'NO')

